type Game = 'blackjack' | 'roulette' | 'slots' | 'coin' | 'dice' | 'krule' | 'bingo';
type Tab = Game | 'sports' | 'mybets' | 'history' | 'lobby';
type Wallet = 'cash' | 'bank';
type BetState = 'pending' | 'won' | 'lost' | 'refunded';
type Card = { rank: string; suit: string; value: number };
type Blackjack = { id: string; status: string; wager: number; payout: number; state: { dealer: Card[]; player: Card[] }; result: { message?: string } };
type Round = { id: string; game: Game; wager: number; payout: number; status: string; result: Record<string, any> };
type Match = { id: string; league: string; league_code?: string | null; league_emblem?: string | null; home_team: string; away_team: string; home_team_id?: number | null; away_team_id?: number | null; home_crest?: string | null; away_crest?: string | null; starts_at: string; status: string; winner?: string; home_score: number | null; away_score: number | null; odds_home: number; odds_draw: number; odds_away: number; matchday?: number | null };
type Bet = { id: string; event_id: string; event?: Match | null; pick: 'home' | 'draw' | 'away'; stake: number; odds: number; possible_payout: number; payout: number; base_payout: number; pool_bonus: number; status: BetState; wallet_source: Wallet; created_at: string; resolved_at?: string };
type Stats = { participants: number; total: number; stakes: { home: number; draw: number; away: number } };
type Data = { wallet: { cash: string; bank: string }; events: Match[]; bets: Bet[]; rounds: Round[]; blackjack: Blackjack | null; sportsEnabled: boolean; sportsStats: Record<string, Stats> };
type RoomMember = { seat: number; isMe: boolean; label: string; avatar?: string | null; wager: number; choice: string | null; status: BetState; payout: number | null };
type Room = { id: string; game: Game; status: 'joining' | 'drawing' | 'settled' | 'cancelled'; starts_at: string; draw_ends_at?: string; finished_at?: string; minPlayers: number; players: RoomMember[]; my: { wager: number; ticket: number[] | null; status: BetState; payout: number | null; choice: string; wallet_source: Wallet } | null; outcome: any; message?: string | null };
type LiveRoom = { id: string; game: Game; status: string; starts_at: string; draw_ends_at: string; participants: number; minPlayers: number; joined: boolean };
type RoomHistory = { room_id: string; wager: number; payout: number; status: string; joined_at: string; room: { game: Game; status: string; starts_at: string } | null };
const NAMES: Record<Game, string> = { blackjack: 'Blackjack', roulette: 'Ruleta', slots: 'Tragaperras', coin: 'Cara o cruz', dice: 'Dados', krule: 'Modo Krule', bingo: 'Bingo en vivo' };
const ICONS: Record<Game, string> = { blackjack: '♠', roulette: '◉', slots: '🎰', coin: '🪙', dice: '⚄', krule: '♛', bingo: '🎱' };
const GAME_RULES: Record<Game, string> = { blackjack: 'Acércate a 21 sin pasarte. Solo: decides cada carta. En mesa: eliges estrategia antes del reparto.', roulette: 'Un único número compartido para toda la sala. El 0 es verde; pleno ×36, rojo/negro/par/impar ×2.', slots: 'Los tres rodillos son iguales para todos en la sala. Tres 7️⃣ ×25; trío ×12; pareja ×2.', coin: 'La misma moneda cae para todos los jugadores. Acierta para cobrar ×2.', dice: 'Un dado para todos. Adivina del 1 al 6 para ganar ×6.', krule: 'Tres dados compartidos. Trío ×8, pareja ×2, suma de 14 o más ×1,5.', bingo: 'Cartones 5×5 diferentes por persona, mínimo 5 jugadores. Bolas en vivo. El bote reparte 20 % para la primera línea y 80 % para el primer bingo.' };
const fmt = (n: any) => Number(n ?? 0).toLocaleString('es-ES');
const dt = (s?: string) => s ? new Date(s).toLocaleString('es-ES', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }) : '—';
const uuid = () => crypto.randomUUID();
const choices = (game: Game): [string, string][] => game === 'roulette' ? [['rojo', 'Rojo'], ['negro', 'Negro'], ['par', 'Par'], ['impar', 'Impar'], ...Array.from({ length: 37 }, (_, i) => [`n:${i}`, `Número ${i}`] as [string, string])] : game === 'coin' ? [['cara', 'Cara'], ['cruz', 'Cruz']] : game === 'dice' ? Array.from({ length: 6 }, (_, i) => [String(i + 1), `Número ${i + 1}`] as [string, string]) : game === 'blackjack' ? Array.from({ length: 5 }, (_, i) => [String(i + 16), `Pedir hasta ${i + 16}`] as [string, string]) : [];
const initialChoice: Record<Game, string> = { blackjack: '17', roulette: 'rojo', slots: '', coin: 'cara', dice: '1', krule: '', bingo: '' };
const pickName = (p: string) => p === 'home' ? '1 · Local' : p === 'draw' ? 'X · Empate' : '2 · Visitante';
const statusName = (s: string) => ({ pending: 'Pendiente', won: 'Premiada', lost: 'Fallada', refunded: 'Reembolsada', joining: 'Inscripción', drawing: 'Sorteando', settled: 'Finalizada', cancelled: 'Cancelada', postponed: 'Aplazado', scheduled: 'Próximo', live: 'En directo', finished: 'Finalizado' } as Record<string, string>)[s] ?? s;
async function api<T = any>(uri: string, data?: unknown): Promise<T> {
    const r = await fetch('/api/betpan' + uri, { method: data === undefined ? 'GET' : 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json' }, body: data === undefined ? undefined : JSON.stringify(data), cache: 'no-store' });
    let x: any; try { x = await r.json() } catch { throw new Error(`El servidor respondió sin JSON (${r.status}). Comprueba el despliegue.`) }
    if (!r.ok) throw new Error(x?.error ?? `Error HTTP ${r.status}`); return x as T;
}
const LEAGUES = [
    { code: 'PD', name: 'LaLiga', short: 'LaLiga' },
    { code: 'PL', name: 'Premier League', short: 'Premier' },
    { code: 'FL1', name: 'Ligue 1', short: 'Ligue 1' },
    { code: 'CL', name: 'Champions League', short: 'Champions' },
    { code: 'EL', name: 'Europa League', short: 'Europa' },
    { code: 'UCL', name: 'Conference League', short: 'Conference' }
] as const;
type LeagueCode = (typeof LEAGUES)[number]['code'];
const leagueCode = (match: Match): LeagueCode => {
    const code = match.league_code ?? match.id.split(':')[1];
    return LEAGUES.find(c => c.code === code)?.code ?? 'PD';
};
const safeImage = (v?: string | null) => typeof v === 'string' && /^https:\/\//i.test(v) ? v : '';
function Crest({ url, name, fallback }: { url?: string | null; name: string; fallback: string }) {
    const [broken, setBroken] = useState(false);
    useEffect(() => setBroken(false), [url]);
    return <span className="bp3-crest" role="img" aria-label={name}>
        {safeImage(url) && !broken ? <img src={url ?? ''} alt="" loading="lazy" onError={() => setBroken(true)} /> : <b>{fallback}</b>}
    </span>;
}
function Shield({ src, name, teamId }: { src?: string | null; name: string; teamId?: number | null }) {
    const url = src ?? (Number.isSafeInteger(teamId) && Number(teamId) > 0 ? `https://crests.football-data.org/${teamId}.svg` : null);
    return <Crest url={url} name={`Escudo de ${name}`} fallback={name.slice(0, 2).toUpperCase()} />;
}
function LeagueMark({ code, url }: { code: LeagueCode; url?: string | null }) {
    const emblem = url ?? `https://crests.football-data.org/${code}.png`;
    return <Crest url={emblem} name={`Logotipo de ${LEAGUES.find(l => l.code === code)?.name ?? code}`} fallback={code} />;
}
function describeRound(r: Round) {
    const x = r.result ?? {};
    if (r.game === 'roulette') return `Número ${x.roll} · ${x.colour ?? ''}`;
    if (r.game === 'slots') return (x.reels ?? []).join('  ');
    if (r.game === 'coin') return `Salió ${x.landed}`;
    if (r.game === 'dice') return `Salió el ${x.landed}`;
    if (r.game === 'krule') return `Dados ${(x.dice ?? []).join(' · ')} · Suma ${x.sum}`;
    return x.message ?? 'Jugada registrada';
}
const isMadridToday = (value: string, now: number) => new Date(value).toLocaleDateString('en-CA', { timeZone: 'Europe/Madrid' }) === new Date(now).toLocaleDateString('en-CA', { timeZone: 'Europe/Madrid' });
const isBetOpen = (match: Match, now: number) => match.status === 'scheduled' && Date.parse(match.starts_at) > now + 120000;
function CardFace({ card }: { card: Card }) { return <div className={'bp2-card ' + (/^[♥♦]$/.test(card.suit) ? 'red' : '')}><b>{card.rank}</b><em>{card.suit}</em></div> }
function Timer({ end, now }: { end: string; now: number }) { const s = Math.max(0, Math.ceil((Date.parse(end) - now) / 1000)); return <span className={'bp2-timer ' + (s < 8 ? 'urgent' : '')}>{String(Math.floor(s / 60)).padStart(2, '0')}:{String(s % 60).padStart(2, '0')}</span> }
function SportsMatch({ e, stats, onBet, busy, valid, now }: { e: Match; stats?: Stats; onBet: (e: Match, p: Bet['pick'], odds: number) => void; busy: boolean; valid: boolean; now: number }) {
    const start = Date.parse(e.starts_at);
    const upcoming = isBetOpen(e, now);
    const score = e.home_score !== null && e.away_score !== null;
    const kickedOff = start <= now;
    const code = leagueCode(e);
    const label = e.status === 'finished' ? 'FINALIZADO' : e.status === 'live' ? 'EN JUEGO' : e.status === 'scheduled' && kickedOff ? 'INICIO PENDIENTE DE CONFIRMAR' : e.status === 'scheduled' && !upcoming ? 'CIERRA EN 2 MIN' : e.status === 'postponed' ? 'APLAZADO' : e.status === 'cancelled' ? 'CANCELADO' : 'APUESTAS ABIERTAS';
    const remaining = Math.max(0, Math.floor((start - now - 120000) / 60000));
    return <article className={'bp2-match bp3-match ' + (upcoming ? 'bp3-match-open' : 'bp3-match-disabled')}>
        <div className="bp2-match-top bp3-match-top"><span className="bp3-match-competition"><LeagueMark code={code} url={e.league_emblem} /><span><b>{e.league}</b>{e.matchday ? ` · Jornada ${e.matchday}` : ''}</span></span><span className={'bp2-status ' + (upcoming ? 'bp3-open' : e.status === 'live' ? 'live' : '')}>{upcoming ? '● ABIERTAS' : label}</span></div>
        <div className="bp2-match-teams bp3-match-teams">
            <div className="bp2-team"><Shield src={e.home_crest} teamId={e.home_team_id} name={e.home_team} /><strong>{e.home_team}</strong><small>LOCAL</small></div>
            <div className="bp2-score">{score ? <><b>{e.home_score} <span>:</span> {e.away_score}</b><small>{e.status === 'finished' ? 'RESULTADO FINAL' : 'MARCADOR'}</small></> : <><strong>{upcoming ? 'VS' : '—'}</strong><small>{dt(e.starts_at)}</small></>}</div>
            <div className="bp2-team"><Shield src={e.away_crest} teamId={e.away_team_id} name={e.away_team} /><strong>{e.away_team}</strong><small>VISITANTE</small></div>
        </div>
        <div className="bp2-match-pool"><span>◉ {fmt(stats?.participants)} boletos</span><span>Bote virtual · {fmt(stats?.total)} PND</span></div>
        <div className="bp2-markets bp3-markets" aria-label={`Pronósticos: ${e.home_team} contra ${e.away_team}`}>{([['home', '1', 'LOCAL', e.odds_home], ['draw', 'X', 'EMPATE', e.odds_draw], ['away', '2', 'VISITANTE', e.odds_away]] as const).map(([p, t, desc, o]) => <button key={p} disabled={!upcoming || busy || !valid} onClick={() => onBet(e, p, Number(o))} aria-label={`Apostar a ${desc.toLowerCase()}, cuota ${o}`}><span><small>{t}</small><em>{desc}</em></span><strong>×{Number(o).toFixed(2)}</strong></button>)}</div>
        {upcoming ? <p className="bp3-match-hint">Cierre preventivo en {remaining > 60 ? `${Math.floor(remaining / 60)} h ${remaining % 60} min` : `${remaining} min`} · hora local {dt(e.starts_at)}</p> :
            <p className="bp2-match-closed">{e.status === 'finished' ? 'Consulta el resultado y tu premio en «Mis apuestas».' : e.status === 'scheduled' && kickedOff ? 'Ya ha llegado la hora de inicio; pendiente de la siguiente actualización del proveedor.' : e.status === 'scheduled' ? 'A menos de dos minutos del inicio, el mercado está cerrado.' : 'No se aceptan apuestas durante o después del partido.'}</p>}
    </article>;
}
